css:
.sl-method-circles {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    font-family: var(--smartlearn-body-font, inherit);
    padding-block: clamp(3.5rem, 6vw, 6rem);
}
.sl-method-circles h2,
.sl-method-circles h3 {
    font-family: var(--smartlearn-heading-font, inherit);
}
.sl-method-circles .sl-text-muted {
    color: var(--smartlearn-text-muted);
}
.sl-method-circles .sl-container-boxed {
    max-width: 1240px;
    margin: 0 auto;
    padding-inline: 1.5rem;
}
@media (min-width: 992px) {
    .sl-method-circles .sl-container-boxed {
        padding-inline: 2.5rem;
    }
}
.sl-method-circles .sl-badge-eyebrow {
    background-color: var(--smartlearn-card-bg);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent);
    color: var(--smartlearn-primary);
    font-size: 0.85rem;
    font-weight: 700;
    letter-spacing: 0.12em;
}
.sl-method-circles .sl-method-heading {
    font-size: clamp(2.2rem, 3.6vw, 3.1rem);
    font-weight: 800;
    line-height: 1.16;
    letter-spacing: -0.035em;
    color: var(--smartlearn-text);
}
.sl-method-circles .sl-method-lead {
    font-size: 1.125rem;
    line-height: 1.75;
    color: var(--smartlearn-text-muted);
}
.sl-method-circles .sl-accordion-btn {
    padding: 1.15rem 1.65rem;
    background-color: transparent;
    border: 1.5px solid color-mix(in srgb, var(--smartlearn-primary) 30%, var(--smartlearn-card-border));
    color: var(--smartlearn-text);
    transition: border-color 0.3s ease, background-color 0.3s ease, transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
    cursor: pointer;
    box-shadow: 0 4px 15px color-mix(in srgb, var(--smartlearn-text) 4%, transparent);
}
.sl-method-circles .sl-accordion-btn:hover {
    border-color: var(--smartlearn-primary);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 8%, transparent);
    transform: translateX(4px);
}
[dir="rtl"] .sl-method-circles .sl-accordion-btn:hover {
    transform: translateX(-4px);
}
.sl-method-circles .sl-accordion-btn:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
.sl-method-circles .sl-accordion-title {
    font-size: 0.98rem;
    letter-spacing: 0.06em;
    font-weight: 700;
}
.sl-method-circles .sl-accordion-icon {
    width: 42px;
    height: 42px;
    background-color: color-mix(in srgb, var(--smartlearn-text) 12%, transparent);
    color: var(--smartlearn-text);
    transition: background-color 0.3s ease, color 0.3s ease, transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
}
.sl-method-circles .sl-accordion-icon i {
    font-size: 14px;
}
[dir="rtl"] .sl-method-circles .sl-accordion-icon i {
    transform: scaleX(-1);
}
.sl-method-circles .sl-accordion-item.active .sl-accordion-btn {
    border-color: var(--smartlearn-primary);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 10%, transparent);
}
.sl-method-circles .sl-accordion-item.active .sl-accordion-icon {
    background-color: var(--smartlearn-primary);
    color: var(--smartlearn-btn-text);
    transform: rotate(90deg);
}
[dir="rtl"] .sl-method-circles .sl-accordion-item.active .sl-accordion-icon {
    transform: rotate(-90deg);
}
.sl-method-circles .sl-accordion-body-wrapper {
    display: grid;
    grid-template-rows: 0fr;
    transition: grid-template-rows 0.35s cubic-bezier(0.16, 1, 0.3, 1), opacity 0.25s ease;
    opacity: 0;
}
.sl-method-circles .sl-accordion-item.active .sl-accordion-body-wrapper {
    grid-template-rows: 1fr;
    opacity: 1;
}
.sl-method-circles .sl-accordion-body {
    min-height: 0;
    overflow: hidden;
    padding-block: 1.25rem 0.5rem;
    padding-inline: 1.25rem 1.5rem;
    font-size: 1.05rem;
    line-height: 1.75;
}
.sl-method-circles .sl-orbs-stage {
    min-height: 290px;
    background-color: var(--smartlearn-card-bg);
    border-color: var(--smartlearn-card-border);
}
.sl-method-circles .sl-ambient-glow {
    width: 220px;
    height: 220px;
    background: radial-gradient(circle, color-mix(in srgb, var(--smartlearn-primary) 30%, transparent) 0%, transparent 70%);
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    pointer-events: none;
}
.sl-method-circles .sl-orb {
    background-color: color-mix(in srgb, var(--smartlearn-card-bg) 80%, var(--smartlearn-bg));
    border: 1.5px solid var(--smartlearn-card-border);
    color: var(--smartlearn-text);
    box-shadow: 0 10px 25px -5px color-mix(in srgb, var(--smartlearn-text) 10%, transparent);
    transition: scale 0.3s cubic-bezier(0.16, 1, 0.3, 1), border-color 0.3s ease, background-color 0.3s ease;
}
.sl-method-circles .sl-orb:hover {
    scale: 1.08;
    border-color: var(--smartlearn-primary);
    background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, var(--smartlearn-card-bg));
}
.sl-method-circles .sl-orb-lg {
    min-width: 140px;
    min-height: 140px;
    background-color: color-mix(in srgb, var(--smartlearn-primary) 12%, var(--smartlearn-card-bg));
    border-color: color-mix(in srgb, var(--smartlearn-primary) 40%, var(--smartlearn-card-border));
}
.sl-method-circles .sl-orb-lg i {
    color: var(--smartlearn-primary);
}
.sl-method-circles .sl-orb-md {
    min-width: 118px;
    min-height: 118px;
}
.sl-method-circles .sl-orb-sm {
    min-width: 104px;
    min-height: 104px;
}
@keyframes sl-mc-float-1 {
    0% { transform: translateY(0) rotate(0deg); }
    100% { transform: translateY(-10px) rotate(2deg); }
}
@keyframes sl-mc-float-2 {
    0% { transform: translateY(0) scale(1); }
    100% { transform: translateY(-14px) scale(1.03); }
}
@keyframes sl-mc-float-3 {
    0% { transform: translateY(0); }
    100% { transform: translateY(-8px) translateX(4px); }
}
@keyframes sl-mc-float-4 {
    0% { transform: translateY(0); }
    100% { transform: translateY(-12px) translateX(-4px); }
}
@keyframes sl-mc-float-5 {
    0% { transform: translateY(0); }
    100% { transform: translateY(-10px); }
}
@media (prefers-reduced-motion: no-preference) {
    .sl-method-circles .sl-orb-float-1 { animation: sl-mc-float-1 5s ease-in-out infinite alternate; }
    .sl-method-circles .sl-orb-float-2 { animation: sl-mc-float-2 6s ease-in-out infinite alternate; }
    .sl-method-circles .sl-orb-float-3 { animation: sl-mc-float-3 4.5s ease-in-out infinite alternate; }
    .sl-method-circles .sl-orb-float-4 { animation: sl-mc-float-4 5.5s ease-in-out infinite alternate; }
    .sl-method-circles .sl-orb-float-5 { animation: sl-mc-float-5 6.5s ease-in-out infinite alternate; }
}
@media (prefers-reduced-motion: reduce) {
    .sl-method-circles .sl-accordion-btn,
    .sl-method-circles .sl-accordion-icon,
    .sl-method-circles .sl-accordion-body-wrapper,
    .sl-method-circles .sl-orb {
        transition: none;
    }
    .sl-method-circles .sl-accordion-btn:hover,
    .sl-method-circles .sl-orb:hover {
        transform: none;
        scale: none;
    }
}

